-- 移除“既有账号提升管理员”的专用授权链路；新增和修改管理员继续维护业务角色。
-- 使用前向迁移兼容已经应用 036 的数据库，不改写既有迁移 checksum。

-- @step remove_assignment_menu
-- @check SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM sys_menu WHERE permission_code='administrators:assign_roles') THEN 1 ELSE 0 END AS complete;
DELETE FROM sys_menu WHERE permission_code='administrators:assign_roles';

