d FROM sys_permission WHERE code='roles:update'))) AND NOT EXISTS (SELECT 1 FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='roles:write') AND role_id NOT IN (SELECT role_id FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='roles:delete'))) AND NOT EXISTS (SELECT 1 FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='roles:write') AND role_id NOT IN (SELECT role_id FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='roles:permissions'))) AND NOT EXISTS (SELECT 1 FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='system_settings:read') AND role_id NOT IN (SELECT role_id FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='menus:read'))) AND NOT EXISTS (SELECT 1 FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='system_settings:write') AND role_id NOT IN (SELECT role_id FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='menus:create'))) AND NOT EXISTS (SELECT 1 FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='system_settings:write') AND role_id NOT IN (SELECT role_id FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='menus:update'))) AND NOT EXISTS (SELECT 1 FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='system_settings:write') AND role_id NOT IN (SELECT role_id FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='menus:delete'))))) THEN 1 ELSE 0 END AS complete;
DELETE FROM sys_role_permission WHERE permission_id IN (SELECT id FROM sys_permission WHERE code='administrators:assign_roles');

-- @step remove_assignment_permission
-- @replaces-check 036_role_menu_button_permissions/register_button_permissions
-- @check SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM sys_permission WHERE code='administrators:assign_roles') AND (SELECT COUNT(*) FROM sys_permission WHERE code IS NOT NULL AND (code,name) IN (('administrators:create', '新增管理员'), ('administrators:update', '修改管理员'), ('administrators:delete', '删除管理员'), ('administrators:reset_password', '重置管理员密码'), ('roles:create', '新增角色'), ('roles:update', '修改角色'), ('roles:delete', '删除角色'), ('roles:permissions', '设置角色权限'), ('menus:read', '查看菜单'), ('menus:create', '新增菜单'), ('menus:update', '修改菜单'), ('menus:delete', '删除菜单')))=12 THEN 1 ELSE 0 END AS complete;
DELETE FROM sys_permission WHERE code='administrators:assign_roles';
